catalog_script_client.script:
function onLoad() {
   var ga = new GlideAjax('userCalendarFilter');
    ga.addParam('sysparm_name', 'getAvailableCourses');
    ga.addParam('sysparm_user', g_user.userID);

    ga.getXML(processResponse);

    function processResponse(response) {
    //try {
        // Extrair a string JSON do XML de resposta usando o atributo 'answer'
        var answer = response.responseXML.documentElement.getAttribute("answer");
        var availableCourses = JSON.parse(answer); // Parse o JSON para um objeto JavaScript

        // Certifique-se de que o campo existe no formulário
        g_form.clearOptions('training'); // Limpa todas as opções existentes antes de adicionar as novas

        //if (Array.isArray(availableCourses)) {
            availableCourses.forEach(function(course) {
                if (course.sys_id && course.nome) {
                    g_form.addOption('training', course.sys_id, course.nome);
                }
            });
       // }
  //  } catch (e) {

    //  console.error('Erro ao processar resposta: ', e.message);
   // }
}

  //  function processResponse(response) {
   //     var availableCourses = JSON.parse(response);

   //     var courseField = g_form.getField('training');
   //     g_form.clearOptions('training');

   //     availableCourses.forEach(function(course) {
   //         g_form.addOption('training', course.sys_id, course.nome);
   //     });
   // }

}
